import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const timelines = [];
  const disposables = [];
  let loadedTexture = null;

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const paper = colors.paper ?? '#e8ecf2';

  const atlasW = 512;
  const atlasH = 320;
  const planeWidth = 3.2;
  const planeHeight = planeWidth * (atlasH / atlasW);

  const geometry = new ctx.THREE.PlaneGeometry(planeWidth, planeHeight);
  disposables.push(geometry);

  const material = new MeshBasicNodeMaterial({
    transparent: true,
    opacity: 1,
    side: ctx.THREE.FrontSide,
  });
  disposables.push(material);

  const plane = new ctx.THREE.Mesh(geometry, material);
  group.add(plane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  for (const item of items) {
    if (!item || !item.text) continue;
    const fontSize = item.typography?.fontSize ?? 31;
    const textObj = ctx.fontAtlas.createText(String(item.text), {
      fontSize,
      color: paper,
      align: 'left',
      maxWidthPx: 480,
      letterSpacingPx: 0,
    });
    textObj.position.set(-planeWidth * 0.45, -planeHeight * 0.35, 0.05);
    group.add(textObj);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((t) => t?.kill?.());
    if (loadedTexture && loadedTexture.dispose) loadedTexture.dispose();
    disposables.forEach((d) => {
      if (d && d.dispose) d.dispose();
    });
  };

  return group;
}
